mod.css:
p.project-header__pip-instructions.pip-stuck {
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: min(1090px, calc(100% - 40px));
  z-index: 999;
  margin: 0;
  padding: 8px 0;
  background: rgb(253, 253, 253);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}
.pip-spacer { height: 0; }
.project-header__pip-instructions.pip-stuck + .pip-spacer { height: 48px; }

mod.js:
morse.watch('.project-header__pip-instructions', el => {
  if (!el.nextElementSibling || !el.nextElementSibling.classList.contains('pip-spacer')) {
    el.after(morse.el('div', { class: 'pip-spacer' }));
  }
});
morse.on(window, 'scroll', () => {
  morse.$$('.project-header__pip-instructions').forEach(el => {
    const sp = el.nextElementSibling;
    if (!sp || !sp.classList.contains('pip-spacer')) return;
    const top = el.classList.contains('pip-stuck')
      ? sp.getBoundingClientRect().top
      : el.getBoundingClientRect().top;
    el.classList.toggle('pip-stuck', top < 0);
  });
});
